// Extract context from the failed execution
const err = $json.execution.error || {};
const ctx = $json.execution.lastNodeExecuted || 'unknown';
const inputJson = $json.execution.json || $json;
// Pull Idempotency_Hash if present in payload
const hash = inputJson.Idempotency_Hash__c || inputJson.idempotencyHash || null;
const source = inputJson.source || inputJson.Source__c || 'unknown';
return [{ json: {
  hash,
  source,
  errorMessage: (err.message || String(err)).substring(0, 32000),
  errorNode: ctx,
  executionId: $json.execution.id,
  retryCount: (inputJson.retryCount || 0) + 1
} }];

